//! An edge holds a synced `did:webs` key event log to the history it has
//! served: the log it holds and the high-water log it keeps after a delete.
//! An update must extend that history, or supersede its trailing interaction
//! events with a rotation (KERI's superseding recovery); a fork is refused.
//!
//! The logs are `did-hosting-common/tests/fixtures/recovery/`, regenerated by
//! `did-hosting-control/tests/webs_continuation.rs`: one identifier, with
//! `icp, ixn, ixn`, a recovery `icp, rot`, and a fork `icp, ixn'`.

#![cfg(feature = "method-webs")]

use std::time::Duration;

use did_hosting_common::DidSyncUpdate;
use did_hosting_common::did_ops::{DidRecord, content_log_key, did_key};
use did_hosting_common::server::config::StoreConfig;
use did_hosting_common::server::store::{KS_DIDS, KeyspaceHandle, Store};
use did_hosting_server::cache::ContentCache;
use did_hosting_server::control_register::apply_single_update;

const FIXTURES: &str = "../did-hosting-common/tests/fixtures/recovery";
const PUBLIC_URL: &str = "https://example.com";

fn fixture(name: &str) -> String {
    let path = std::path::Path::new(env!("CARGO_MANIFEST_DIR"))
        .join(FIXTURES)
        .join(name);
    std::fs::read_to_string(&path).unwrap_or_else(|e| panic!("{}: {e}", path.display()))
}

fn update(log: &str) -> DidSyncUpdate {
    let aid = fixture("AID");
    DidSyncUpdate {
        mnemonic: aid.clone(),
        did_id: format!("did:webs:example.com:{aid}"),
        log_content: log.to_string(),
        witness_content: None,
        version_count: 1,
        disabled: false,
    }
}

async fn store() -> (tempfile::TempDir, Store, KeyspaceHandle) {
    let dir = tempfile::tempdir().expect("temp dir");
    let store = Store::open(&StoreConfig {
        data_dir: dir.path().to_path_buf(),
        ..StoreConfig::default()
    })
    .await
    .expect("open store");
    let ks = store.keyspace(KS_DIDS).expect("dids ks");
    (dir, store, ks)
}

async fn sync(store: &Store, ks: &KeyspaceHandle, log: &str) -> Result<(), String> {
    let cache = ContentCache::new(Duration::from_secs(60));
    apply_single_update(ks, store, &update(log), &cache, Some(PUBLIC_URL))
        .await
        .map(|_| ())
        .map_err(|e| e.to_string())
}

async fn held(ks: &KeyspaceHandle) -> String {
    let bytes = ks
        .get_raw(content_log_key(&fixture("AID")))
        .await
        .unwrap()
        .expect("a held log");
    String::from_utf8(bytes).unwrap()
}

#[tokio::test]
async fn a_fork_is_refused_and_a_recovery_is_applied() {
    let (_dir, store, ks) = store().await;
    let interactions = fixture("ixn-ixn.keri.cesr");
    sync(&store, &ks, &interactions).await.expect("first sync");

    let err = sync(&store, &ks, &fixture("other-ixn.keri.cesr"))
        .await
        .expect_err("a different interaction at sequence 1 is a fork");
    assert!(err.contains("diverges"), "{err}");
    assert_eq!(held(&ks).await, interactions, "the held log is kept");

    let recovery = fixture("rot.keri.cesr");
    sync(&store, &ks, &recovery)
        .await
        .expect("a rotation supersedes the interactions");
    assert_eq!(held(&ks).await, recovery);
}

/// After a delete, the high-water log still holds the slot to its history:
/// the superseded interactions cannot come back.
#[tokio::test]
async fn the_high_water_log_outlives_a_delete() {
    let (_dir, store, ks) = store().await;
    sync(&store, &ks, &fixture("rot.keri.cesr"))
        .await
        .expect("first sync");

    let aid = fixture("AID");
    let mut batch = store.batch();
    batch.remove(&ks, did_key(&aid));
    batch.remove(&ks, content_log_key(&aid));
    batch.commit().await.unwrap();
    assert!(ks.get::<DidRecord>(did_key(&aid)).await.unwrap().is_none());

    let err = sync(&store, &ks, &fixture("ixn-ixn.keri.cesr"))
        .await
        .expect_err("the high-water rotation cannot be superseded");
    assert!(err.contains("the hosted event is rot"), "{err}");
    sync(&store, &ks, &fixture("rot.keri.cesr"))
        .await
        .expect("the same log syncs again");
}
